import{_ as e,o as s,c as o,aw as l}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Перенос репозитория","description":"","frontmatter":{},"headers":[],"relativePath":"common/git/usecase/repo-transfer.md","filePath":"wiki/dev-commit/common/git/usecase/repo-transfer.md"}'),t={name:"common/git/usecase/repo-transfer.md"};function r(n,a,i,c,p,d){return s(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="перенос-репозитория" tabindex="-1">Перенос репозитория <a class="header-anchor" href="#перенос-репозитория" aria-label="Permalink to &quot;Перенос репозитория&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><ul><li>Команды <code>git clone --mirror</code> и <code>git push --mirror</code> используются для полной синхронизации содержимого одного удалённого репозитория с другим</li></ul><h2 id="clone" tabindex="-1">clone <a class="header-anchor" href="#clone" aria-label="Permalink to &quot;clone&quot;">​</a></h2><ul><li>Команда создаёт &quot;зеркальный&quot; локальный репозиторий, который хранит все ветки и теги</li></ul><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> clone</span><span style="color:#986801;"> --mirror</span><span style="color:#50A14F;"> UrlИсходногоРепозитория</span></span></code></pre></div><h2 id="push" tabindex="-1">push <a class="header-anchor" href="#push" aria-label="Permalink to &quot;push&quot;">​</a></h2><ul><li>Команда перенесёт все данные из локального зеркального репозитория в указанный удалённый репозиторий</li><li>Она копирует все ветки, теги и рефы из локального репозитория в указанный удалённый репозиторий, полностью заменяя его содержимое</li></ul><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> push</span><span style="color:#986801;"> --mirror</span><span style="color:#50A14F;"> UrlНовогоРепозитория</span></span></code></pre></div><h3 id="варианты" tabindex="-1">Варианты <a class="header-anchor" href="#варианты" aria-label="Permalink to &quot;Варианты&quot;">​</a></h3><ul><li><code>git push --all</code> - отправляет только все ветки, но не теги, при этом, если в новом репозитории уже есть ветки, то они останутся</li><li><code>git push --tags</code> - отправляет только теги</li><li><code>git push --mirror</code> - отправляет всё (ветки, теги, рефы) и заменяет содержимое удалённого репозитория</li></ul>',11)])])}const m=e(t,[["render",r]]);export{u as __pageData,m as default};
